BEGIN;
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT uuidv7(),email text NOT NULL,name text NOT NULL,password_hash text NOT NULL,status text NOT NULL DEFAULT 'active' CHECK(status IN('active','disabled','pending')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX users_email_unique_ci ON users(lower(email));
CREATE TABLE auth_sessions(id uuid PRIMARY KEY DEFAULT uuidv7(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,token_hash text NOT NULL UNIQUE,expires_at timestamptz NOT NULL,revoked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX auth_sessions_user_active_idx ON auth_sessions(user_id,expires_at) WHERE revoked_at IS NULL;
CREATE TABLE schools(id uuid PRIMARY KEY DEFAULT uuidv7(),code text NOT NULL UNIQUE,name text NOT NULL,status text NOT NULL DEFAULT 'active' CHECK(status IN('active','suspended','archived')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE school_memberships(id uuid PRIMARY KEY DEFAULT uuidv7(),school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,role text NOT NULL CHECK(role IN('student','teacher','supervisor','school_admin','parent')),status text NOT NULL DEFAULT 'active' CHECK(status IN('active','suspended','graduated','revoked')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(school_id,user_id,role));
CREATE INDEX school_memberships_scope_idx ON school_memberships(school_id,role,status,user_id);
CREATE TABLE paths(id uuid PRIMARY KEY DEFAULT uuidv7(),code text NOT NULL UNIQUE,name text NOT NULL,status text NOT NULL DEFAULT 'active',presentation jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE subjects(id uuid PRIMARY KEY DEFAULT uuidv7(),path_id uuid NOT NULL REFERENCES paths(id) ON DELETE CASCADE,code text NOT NULL,name text NOT NULL,presentation jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(path_id,code));
CREATE TABLE skills(id uuid PRIMARY KEY DEFAULT uuidv7(),subject_id uuid NOT NULL REFERENCES subjects(id) ON DELETE CASCADE,parent_skill_id uuid REFERENCES skills(id) ON DELETE RESTRICT,code text NOT NULL,name text NOT NULL,kind text NOT NULL CHECK(kind IN('main','sub')),sort_order integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(subject_id,code));
CREATE INDEX skills_subject_parent_idx ON skills(subject_id,parent_skill_id,kind,sort_order);
CREATE TABLE assets(id uuid PRIMARY KEY DEFAULT uuidv7(),object_key text NOT NULL UNIQUE,public_url text,mime_type text NOT NULL,size_bytes bigint NOT NULL CHECK(size_bytes>=0),sha256 text,version integer NOT NULL DEFAULT 1 CHECK(version>0),status text NOT NULL DEFAULT 'active' CHECK(status IN('active','orphan_candidate','archived')),created_by uuid REFERENCES users(id) ON DELETE SET NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX assets_sha256_idx ON assets(sha256) WHERE sha256 IS NOT NULL;
CREATE TABLE questions(id uuid PRIMARY KEY DEFAULT uuidv7(),question_code text NOT NULL UNIQUE,current_version integer NOT NULL DEFAULT 1 CHECK(current_version>0),workflow_status text NOT NULL DEFAULT 'draft' CHECK(workflow_status IN('draft','pending_review','approved','rejected','archived')),owner_type text NOT NULL DEFAULT 'platform' CHECK(owner_type IN('platform','teacher','school')),owner_id uuid,created_by uuid REFERENCES users(id) ON DELETE SET NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE question_versions(question_id uuid NOT NULL REFERENCES questions(id) ON DELETE RESTRICT,version integer NOT NULL,question_type text NOT NULL CHECK(question_type IN('mcq','true_false','essay')),text_content text NOT NULL DEFAULT '',image_asset_id uuid REFERENCES assets(id) ON DELETE SET NULL,image_alt text NOT NULL DEFAULT '',options_embedded_in_image boolean NOT NULL DEFAULT false,correct_option_index integer,explanation text NOT NULL DEFAULT '',hint text NOT NULL DEFAULT '',solving_strategy text NOT NULL DEFAULT '',video_url text,source_meta jsonb NOT NULL DEFAULT '{}'::jsonb,ai_context jsonb NOT NULL DEFAULT '{}'::jsonb,voice_explanation jsonb NOT NULL DEFAULT '{}'::jsonb,difficulty text,exam_type text,source text,source_year integer,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(question_id,version),CHECK(text_content<>'' OR image_asset_id IS NOT NULL));
CREATE TABLE question_options(question_id uuid NOT NULL,version integer NOT NULL,option_index integer NOT NULL,option_text text NOT NULL DEFAULT '',asset_id uuid REFERENCES assets(id) ON DELETE SET NULL,PRIMARY KEY(question_id,version,option_index),FOREIGN KEY(question_id,version) REFERENCES question_versions(question_id,version) ON DELETE CASCADE);
CREATE TABLE question_skill_links(question_id uuid NOT NULL REFERENCES questions(id) ON DELETE CASCADE,skill_id uuid NOT NULL REFERENCES skills(id) ON DELETE RESTRICT,relation_type text NOT NULL CHECK(relation_type IN('main','sub','secondary')),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(question_id,skill_id));
CREATE INDEX question_skill_links_skill_idx ON question_skill_links(skill_id,question_id);
COMMIT;
